import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-03-26 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-03-26 :: Ceph Performance Meeting","date":"2020-03-26T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph性能优化","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-26_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-03-26_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2020/2020-03-26_-_-_Ceph_Performance_Meeting.md"};function o(n,l,s,u,h,g){return a(),i("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>会议时间</strong>: 2020年3月26日</li><li><strong>参会人员</strong>: Greg, Igor, Ilya, Mark Cogan 等相关人员</li><li><strong>会议主题</strong>: 讨论Ceph存储系统性能优化和相关PR（Pull Request）的进展</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>Ephemeral Sharding PR</strong>:</p><ul><li>Greg询问Ephemeral Sharding PR的进展，目前还在更新中，尚未完全确认其状态。</li></ul></li><li><p><strong>Locking Improvement PR</strong>:</p><ul><li>讨论了一个改变锁定机制的PR，旨在减少全局锁的生命周期并引入适当的文件锁定。</li><li>Igor表达了对该PR的担忧，担心在当前架构下难以实现。</li></ul></li><li><p><strong>OSD和缓存管理性能问题</strong>:</p><ul><li>讨论了OSD在处理大量数据时，由于缓存管理不当导致的性能下降问题。</li><li>发现OSD在达到缓存限制后，开始从磁盘读取数据，导致页面缓存增加，最终引发内核交换，严重影响性能。</li><li>提出解决方案包括禁用BlueFS的缓冲I/O，以避免使用页面缓存作为辅助缓存。</li></ul></li><li><p><strong>Kernel RBD性能瓶颈</strong>:</p><ul><li>Ilya和Greg讨论了Kernel RBD在单客户端进行顺序读取时的性能瓶颈。</li><li>发现当I/O深度超过64时，内核中的内存复制操作时间增加，影响性能。</li><li>讨论了可能的解决方案，包括检查内核锁的状态和网络堆栈的行为。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><p><strong>禁用BlueFS缓冲I/O</strong>:</p><ul><li>决定禁用BlueFS的缓冲I/O，以避免使用页面缓存，从而提高系统的稳定性和性能。</li><li>Josh将创建相关的PR。</li></ul></li><li><p><strong>PR的合并和测试</strong>:</p><ul><li>确认将合并和测试相关的PR，包括Adam的Column Family Sharding PR和Igor的缓存缩减PR。</li><li>计划在下一个点发布版本中包含这些改进。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>PR的进一步审查和测试</strong>: <ul><li>继续审查和测试涉及的PR，确保它们在合并前达到稳定状态。</li></ul></li><li><strong>性能测试和分析</strong>: <ul><li>进行更多的性能测试，特别是在单网络接口下的测试，以进一步分析和解决性能瓶颈。</li></ul></li><li><strong>内核锁和网络堆栈的深入分析</strong>: <ul><li>使用perf和lockstat等工具，深入分析内核锁和网络堆栈的行为，以找出性能问题的根本原因。</li></ul></li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>未来会议和性能优化</strong>: <ul><li>讨论了即将到来的会议和可能的性能优化话题，包括对Boost和MDS的进一步优化。</li></ul></li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><ul><li>会议结束时，Greg感谢所有参与者的贡献，并期待在下一次会议中能有更多的进展和解决方案。</li></ul>',13)])])}const p=e(t,[["render",o]]);export{_ as __pageData,p as default};
